 "content": "from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]

    def marker_period(lines):
        by_color = {}
        for pos, color in lines:
            by_color.setdefault(color, []).append(pos)
        if not by_color:
            return None
        # Repeated separator stripes identify the unit length. If only one
        # separator exists, its position plus one is the unit length.
        chosen = min(by_color, key=lambda c: len(by_color[c]))
        positions = by_color[chosen]
        if len(positions) >= 2:
            return min(b - a for a, b in zip(positions, positions[1:]))
        return positions[0] + 1

    row_period = marker_period([
        (r, row[0]) for r, row in enumerate(grid)
        if len(set(row)) == 1
    ])
    col_period = marker_period([
        (c, grid[0][c]) for c in range(w)
        if len({grid[r][c] for r in range(h)}) == 1
    ])

    if row_period is not None and (col_period is None or row_period <= col_period):
        out = [[background] * w for _ in range(h)]
        for r in range(h):
            residue = r % row_period
            for c in range(w):
                values = [grid[k][c] for k in range(residue, h, row_period)]
                non_bg = [v for v in values if v != background]
                out[r][c] = Counter(non_bg).most_common(1)[0][0] if non_bg else background
        return out
    if col_period is not None:
        out = [[background] * w for _ in range(h)]
        for c in range(w):
            residue = c % col_period
            for r in range(h):
                values = [grid[r][k] for k in range(residue, w, col_period)]
                non_bg = [v for v in values if v != background]
                out[r][c] = Counter(non_bg).most_common(1)[0][0] if non_bg else background
        return out
    return [list(row) for row in grid]
